\label{dfn_typical}
  Let $(V_1, V_2, V_3)$ be a triple of sets (not necessarily regular) with densities $d_{ij}p$ between $V_i$ and $V_j$.
  \begin{enumerate}[(A)]
  \item
    Fix a vertex $v \in V_1$ and for $i \in \{2, 3\}$, let $N_i = N(v) \cap V_i$. We say that $v$ is \emph{$\varepsilon$-typical} if for $i \in \{2, 3\}$,
    \begin{enumerate}[(i)]
      \setlength{\itemsep}{1pt}
      \setlength{\parskip}{0pt}
      \setlength{\parsep}{0pt}
    \item
      $|N_i| = (1 \pm \varepsilon)d_{1i}p|V_i|$ and
    \item
      there exists $N_i'\subset N_i$ satisfying $|N_i'| \ge (1 - \varepsilon)|N_i|$ such that $(N_2', N_3')$ is an $(\varepsilon,p)$-regular pair with density $(1 \pm \varepsilon)d_{23}p$.
    \end{enumerate}
  \item
    The triple $(V_1,V_2,V_3)$ is \emph{$\varepsilon$-typical} if it is $(\varepsilon,p)$-regular and for each $i$, all but at most $\varepsilon|V_i|$ vertices in $V_i$ are $\varepsilon$-typical.
  \end{enumerate}

\label{lemma_typicalregulartriple}
  For all positive $\beta$, $\delta$, $\varepsilon'$, and $\xi$, there exist constants $\varepsilon_0(\beta, \delta, \varepsilon')$ and $C(\delta, \varepsilon', \xi)$ such that if $\varepsilon \leq \varepsilon_0$, $d_{12}, d_{13}, d_{23} \geq \delta$, $\xi n \leq n_1, n_2, n_3 \leq n$, and $p \geq Cn^{-1/2}$, then all but at most
  \[
  \beta^{\delta\xi^2n^2p} {n_1n_2 \choose d_{12}pn_1n_2} {n_1n_3 \choose d_{13}pn_1n_3} {n_2n_3 \choose d_{23}pn_2n_3}
  \]
  graphs in $ \mathcal{G}(K_3,(n_1, n_2, n_3),(d_{12}, d_{13}, d_{23}),(\varepsilon,p)) $ are $\varepsilon'$-typical provided that $n$ is sufficiently large.

Note that without loss of generality, we may assume that $\alpha \leq 1/2$. Furthermore, let $\varepsilon = \min\{\delta/4, \alpha/20\}$ and let $\varepsilon' = 2\varepsilon/\alpha$. Let us greedily remove triangles from $(V_1, V_2, V_3)$ until we cannot do it anymore and denote the remaining triple by $(V'_1, V'_2, V'_3)$. If $|V'_i| \leq \alpha|V_i|$ for some $i$, then there is nothing left to prove, so we may assume that $|V'_i| > \alpha|V_i|$ for all $i$. Let $W_i$ be the set of all those vertices in $V'_i$ that were $\varepsilon$-typical in the original triple and note that $|W_i| \geq |V'_i| - \varepsilon|V_i| \geq (\alpha/2)|V_i|$. By Proposition~\ref{prop_inheritregularity}, the triple $(W_1, W_2, W_3)$ is $(\varepsilon', p)$-regular and the density of each pair $(W_i, W_j)$ is at least $(d_{ij} - \varepsilon)p$. Since $\varepsilon' < 1/2$, there is a vertex $v \in W_1$ with $\deg(v,W_i) \geq (d_{ij}-\varepsilon-\varepsilon')p|W_i|$ for $i \in \{2, 3\}$. For $i \in \{2, 3\}$, let $N_i$ and $N'_i$ be the sets from the definition of an $\varepsilon$-typical vertex for $v$ and let $M_i = N_i \cap W_i$ and $M'_i = N'_i \cap W_i$. Since
  \begin{align*}
    |M'_i| & \geq |M_i| - |N_i \setminus N'_i| \geq (d_{1i} - \varepsilon - \varepsilon')p|W_i| - \varepsilon(1+\varepsilon)d_{1i}p|V_i| \\
    & \geq \big[ (1 - \varepsilon/\delta - \varepsilon'/\delta)(\alpha/2) - \varepsilon(1+\varepsilon) \big] d_{1i}p|V_i| \geq \varepsilon(1+\varepsilon)d_{1i}p|V_i| \geq \varepsilon|N'_i|
  \end{align*}
  and $(N'_2, N'_3)$ was $(\varepsilon,p)$-regular with density at least $(1-\varepsilon)\delta p$ and $(1-\varepsilon)\delta p > \varepsilon p$, the pair $(M'_2, M'_3)$ has positive density. It follows that $(W_1, W_2, W_3)$ contains a triangle, but this is impossible.

\label{prop_goodtriangles}
  Let $\varepsilon$, $\delta$, and $p$ be positive constants with
  $\varepsilon < 1/2$. Let $(V_1, V_2, V_3)$ be a triple of sets such
  that for all $i$ and $j$, the density of $(V_i, V_j)$ is $d_{ij}p$, where
  $d_{ij} \geq \delta$. Then for every $\varepsilon$-typical vertex $v \in V_1$,
  there exist sets $N''_j \subset N(v) \cap V_j$ for $j \in \{2,3\}$
  such that
  \begin{enumerate}[(i)]
    \setlength{\itemsep}{1pt}
    \setlength{\parskip}{0pt}
    \setlength{\parsep}{0pt}
  \item \label{item_goodtriangles_i}
    there are at least $(1-6\varepsilon-2\varepsilon/\delta)d_{12}d_{13}d_{23}p^3|V_2||V_3|$ edges in $(N''_2,N''_3)$ and if $v$ is $\varepsilon$-good, then there are at least that many $\varepsilon$-good edges in $(N''_2, N''_3)$, and
  \item \label{item_goodtriangles_ii}
    for all $j$ and $k$ with $\{j,k\} = \{2,3\}$, no vertex in $N''_j$ has more than $(1+2\varepsilon/\delta)(1+\varepsilon^2)d_{1k}d_{23}p^2|V_k|$ neighbours in $N''_k$.
  \end{enumerate}

\label{prop_Hall}
  Let $H$ be a bipartite graph on the vertex set $A \cup B$ with $|A| = |B|$. Suppose that there is an integer $L$ such that
  \begin{enumerate}[(i)]
  \setlength{\itemsep}{1pt}
  \setlength{\parskip}{0pt}
  \setlength{\parsep}{0pt}
  \item
    $|N(S)| \geq |S|$ for each $S \subset A$ with $|A \setminus S| \geq L$ and
  \item
    $|N(T)| \geq |T|$ for each $T \subset B$ with $|T| \leq L$.
  \end{enumerate}
  Then $H$ has a perfect matching.

\label{prop_randomgraphproperties1}
For every positive real $\rho$, there exists a constant $C(\rho)$
such that if $p \ge C(\log n/n)^{1/2}$, then $G(n,p)$ a.a.s.~satisfies the
following properties.
\begin{enumerate}[(i)]
    \setlength{\itemsep}{1pt} \setlength{\parskip}{0pt}
  \setlength{\parsep}{0pt}
  \item Every vertex has degree $(1 \pm \rho)np$.
  \item Every pair of distinct vertices has $(1 \pm \rho)np^2$ common neighbours.
  \item For all $X,Y \subset V$ with $|X|,|Y| \ge \rho np$, we have $e(X,Y) = (1 \pm \rho)|X||Y|p$. In particular,
  $e(X) = e(X,X)/2 = (1 \pm \rho)|X|^2p/2$ for all $X$ of size at least $\rho np$.
\end{enumerate}

Let $\varepsilon = \min\{1/100, \delta/50\}$. Fix $i$, $j$, and $k$ with $\{i,j,k\} = \{1,2,3\}$. For 
 each vertex $v \in V_i$, let $N_j = N(v) \cap V_j$ and $N_k = N(v) \cap V_k$. By construction, $M_{12} \cup M_{13} \cup M_{23}$ is a matching.

  \begin{CLAIM}
    \label{claim_M1}
    With probability $1 - o(1)$, $(\eta/2)m \leq|M_{ij}| \le 2\eta m$.
  \end{CLAIM}
  \begin{proof}
    By our assumption on $|E_{ij}|$, there are at least $(1-\eta)d_{ij}pm^2$ edges in $(V_i, V_j) \setminus E_{ij}$, so
    $\mathbb{E}[|M'_{ij}|] \ge (1 - \eta)d_{ij}pm^2q_{ij} = (1 - \eta)\eta m$, and Chernoff's inequality implies that $|M'_{ij}| \geq (3\eta/4)m$ with probability $1 - o(1)$. In order to estimate $|M_{ij}|$, note that $|M'_{ij}| - |M_{ij}|$ is at most the number of vertices in $V_i \cup V_j$ that are incident to an edge of $M'_{ij}$ and some other edge in $M'_{12} \cup M'_{13} \cup M'_{23}$. Let $\mathcal{A}_w$ denote the event that $w$ is such a ``bad'' vertex. Since $(V_1, V_2, V_3)$ is $(\delta, \varepsilon, p)$-super-regular, $\deg(v, V_j) \leq (1+\varepsilon)d_{ij}pm$ and $\deg(v, V_k) \leq (1+\varepsilon)d_{ik}pm$ for every $v \in V_i$. Hence, if $w \in V_i$, then
                                        
    \[
    P(\mathcal{A}_w) \leq \deg(w, V_j)q_{ij} \cdot (\deg(w,V_j)q_{ij} + \deg(w,V_k)q_{ik}) \leq (1+\varepsilon)^22\eta^2
    \]
    and the expected number of such ``bad'' vertices in $V_i$ is at most $(1+\varepsilon)^22\eta^2m$.
    The events $\{\mathcal{A}_w \colon w \in V_i\}$ are mutually independent, so by Chernoff's inequality, with probability at least $1 - o(m^{-1})$, there are at most $3\eta^2m$ ``bad'' vertices in $V_i$ and similarly, there are at most $3\eta^2m$ ``bad'' vertices in $V_j$. Hence, $|M_{ij}| \geq (3/4 - 6\eta)\eta m \geq (\eta/2)m$ with probability $1 - o(1)$. Finally, since the number of edges in $(V_i, V_j) \setminus E_{ij}$ is at most $d_{ij}pm^2$, we have $\mathbb{E}[|M'_{ij}|] \le d_{ij}pm^2q_{ij} = \eta m$, and Chernoff's inequality implies that $|M_{ij}| \leq |M'_{ij}| \leq 2\eta m$ with probability $1 - o(1)$.
  \end{proof}

  \begin{CLAIM}
    \label{claim_M2}
    For each fixed vertex $v$, with probability $1 - o(m^{-1})$, we have $\deg(v, Q_j) \leq 3\eta d_{ij}pm$.
  \end{CLAIM}
  \begin{proof}
    Let $Q'_i$ be the set of vertices in $V_i$ that are covered by some edge in $M'_{ij} \cup M'_{ik}$ and note that $Q'_i \supset Q_i$ (similarly define $Q_j'$ and $Q_k'$). For a vertex $w \in V_j$, let $\mathcal{B}_w$ denote the event that $w \in Q'_j$. Since $(V_1, V_2, V_3)$ is $(\delta, \varepsilon, p)$-super-regular, $\deg(w, V_i) \leq (1+\varepsilon)d_{ij}pm$ and $\deg(w, V_k) \leq (1+\varepsilon)d_{jk}pm$. Hence,
    \[
    P(\mathcal{B}_w) \leq \deg(w,V_j)q_{ij} + \deg(w,V_k)q_{ik} \leq 2(1+\varepsilon)\eta.
    \]
    The events $\{\mathcal{B}_w \colon w \in V_j\}$ are mutually independent and $|N_j| \geq (\delta/2)pm$, so by Chernoff's inequality, $|N_j \cap Q'_j| \leq (5\eta/2)|N_j|$ with probability at least $1 - e^{-c\eta\delta pm}$ for some absolute positive constant $c$. It follows that
    \[
    \deg(v, Q_j) \leq \deg(v, Q'_j) = |N_j \cap Q'_j| \leq (5\eta/2)(1+\varepsilon)d_{ij}pm \leq 3\eta d_{ij}pm
    \]
    with probability $1 - o(m^{-1})$.
  \end{proof}

  \begin{CLAIM}
    \label{claim_M3}
    For each fixed $v \in V'_i$, with probability $1 - o(m^{-1})$, the pair $(N_j, N_k)$ contains at least $(\eta / 2)d_{ij}d_{ik}p^2m$ edges of $M_{jk}$.
  \end{CLAIM}
  \begin{proof}
    Without loss of generality, we may assume that $(i,j,k) = (1,2,3)$. Since $v$ is $\varepsilon$-typical, $(1+\varepsilon^2)(1+2\varepsilon/\delta) \leq 2$, and $5\varepsilon + 2\varepsilon/\delta \leq 1/7$, Proposition~\ref{prop_goodtriangles} implies that there are sets $N''_2 \subset N_2$ and $N''_3 \subset N_3$ such that $(N''_2, N''_3)$ contains at least $(6/7)d_{12}d_{13}d_{23}p^3m^2$ edges, no vertex in $N''_2$ has more than $2d_{13}d_{23}p^2m$ neighbours in $N''_3$, and vice versa, no vertex in $N''_3$ has more than $2d_{12}d_{23}p^2m$ neighbours in $N''_2$. Since at most $\eta d_{12}d_{13}d_{23}p^3m^2$
    edges among $(N''_2, N''_3)$ belong to $E_{23}$ by either (A1) or (A2), it follows that
    \[
    \mathbb{E}[| M'_{23} \cap (N''_2, N''_3) | ] \geq (5/7)d_{12}d_{13}d_{23}p^3m^2q_{23} = (5/7)d_{12}d_{13}\eta p^2m.
    \]
    Since $|M'_{23} \cap (N''_2, N''_3)|$ is a sum of independent indicator random variables, Chernoff's inequality implies that for some absolute constant $c$,
    \[
    P\left( | M'_{23} \cap (N''_2, N''_3) | \geq (4/7)d_{12}d_{13}\eta p^2m \right) \geq 1 - e^{-c\eta\delta^2p^2m} \geq 1 - 1/m^2,
    \]
    provided that $C$ is sufficiently large.

    In order to estimate $|M_{23} \cap (N''_2, N''_3)|$, note that $|M'_{23} \cap (N''_2, N''_3)| - |M_{23} \cap (N''_2, N''_3)|$ is at most the number of vertices in $N''_2 \cup N''_3$ that are incident to an edge in $M'_{23} \cap (N''_2, N''_3)$ and some other edge in $M'_{12} \cup M'_{13} \cup M'_{23}$. Let $\mathcal{C}_w$ denote the event that $w$ is such a ``bad'' vertex. If $w \in N''_2$, then
    \begin{align*}
      P(\mathcal{C}_w) & \leq \deg(w, N''_3)q_{23} \cdot (\deg(w,V_3)q_{23} + \deg(w,V_1)q_{12}) \\
      & \leq 2d_{13}d_{23}p^2mq_{23} \cdot ((1+\varepsilon)d_{23}pmq_{23} + (1+\varepsilon)d_{12}pmq_{12}) = (1+\varepsilon)4\eta^2d_{13}\eta^2p.
    \end{align*}
    Since $|N''_2| \leq |N_2| \leq (1+\varepsilon)d_{12}pm$, the expected number of such ``bad'' vertices in $N''_2$ is at most $(1+\varepsilon)^24\eta^2d_{12}d_{23}p^2m$. The events $\{\mathcal{C}_w \colon w \in N''_2\}$ are mutually independent, so by Chernoff's inequality, for some absolute constant $c$, with probability at least $1 - e^{-c\delta^2\eta^2p^2m}$, there are at most $5\eta^2d_{12}d_{13}p^2m$ ``bad'' vertices in $N''_2$ and similarly, there are at most $5\eta^2d_{12}d_{13}p^2m$ ``bad'' vertices in $N''_3$. Hence, with probability $1 - o(m^{-1})$,
    \[
    |M_{23} \cap (N''_2, N''_3)| \geq (4/7 - 10\eta)d_{12}d_{13}\eta p^2m \geq (\eta/2)d_{12}d_{13}p^2m,
    \]
    provided that $C$ is sufficiently large.
  \end{proof}

  \begin{CLAIM}
    \label{claim_M4}
    With probability $1 - o(1)$, the endpoints of every $\eta$-good edge in $(V_j, V_k)$ have at least $(1-4\eta)d_{ij}d_{ik}p^2m$ common neighbours in $V_i \setminus Q_i$.
  \end{CLAIM}
  \begin{proof}
    For an arbitrary vertex $v \in V_i$, let $\mathcal{D}_v$ denote the event that $v \in Q'_i$. Clearly,
    \[
    P(\mathcal{D}_v) \leq \deg(v,V_j)q_{ij} + \deg(v,V_k)q_{ik} \leq 2(1+\varepsilon)\eta.
    \]
    Fix some $\eta$-good edge in $(V_j, V_k)$ and let $A \subset V_i$ be the set of common neighbours of its endpoints. Then $\mathbb{E}[|A \cap Q'_i|] = \sum_{v \in A} P(\mathcal{D}_v) \le |A| \cdot 2(1+\varepsilon)\eta$.
    Moreover by definition, $|A| \geq (1-\eta)d_{ij}d_{ik}p^2m \geq
    (1/2)\delta^2p^2m$. Since the events $\mathcal{D}_v$ are mutually
    independent, Chernoff's inequality implies that
    \[
    P(|A \cap Q'_i| \geq 3\eta|A|) \leq e^{-c\delta^2\eta p^2m}
    \]
    for some absolute positive constant $c$. Hence, if $C$ is sufficiently large, then with probability at least $1 - 1/m^3$,
    \[
    |A \setminus Q_i| \geq |A \setminus Q'_i| \geq (1-3\eta)|A| \geq (1-3\eta)(1-\eta)d_{ij}d_{ik}p^2m \geq (1-4\eta)d_{ij}d_{ik}p^2m.
    \]
    Since there are at most $m^2$ good edges, the claim is proved.
  \end{proof}

  Finally, note that Claims~\ref{claim_M1}--\ref{claim_M4} imply that (M1)--(M4) are satisfied with probability $1 - o(1)$ (one needs to apply the union bound over all choices of
  vertices in order to deduce (M2) and (M3) from \ref{claim_M2} and \ref{claim_M3}).

\label{lemma_main}
  For all positive constants $\delta$, $\xi$, and $\eta$ with $\eta \leq 1/140$, there exist constants $C(\delta,\eta,\xi)$ and $\varepsilon(\delta,\eta)$ such that if $p \geq C(\log n/n)^{1/2}$, then $G(n,p)$ a.a.s.~satisfies the following. Let $(W_1,W_2,W_3)$ be a $(\delta, \varepsilon, p)$-strong-super-regular triple in a subgraph of $G(n,p)$ such that $|W_1| = |W_2| = |W_3| \geq \xi n$. Then there exist edge sets $M_{12}$, $M_{13}$, $M_{23}$ and vertex sets $X_1$, $X_2$, $X_3$ with the following properties:
  \begin{enumerate}
  \item[(P1)]
    $M_{12} \cup M_{13} \cup M_{23}$ is a matching.
  \item[(P2)]
    For all $j$ and $k$, $M_{jk} \subset (W_j,W_k)$ and $(\eta/2) |W_j| \le |M_{jk}| \le 2\eta |W_j| $.
  \item[(P3)]
    For all $i$, $|X_i| \leq (\eta / 4)|W_i|$ and $X_i \subset W_i \setminus Q_i$, where $Q_i$ is the set of vertices in $W_i$ that are covered by some edge in $M_{ij} \cup M_{ik}$.
  \item[(P4)]
    \label{item_factorZi}
    For all $i$, $j$, and $k$, if $Z_i \subset W_i$ has size $|M_{jk}|$ and contains $X_i$, then the subgraph of $(W_1,W_2,W_3)$ induced by $Z_i$ and $M_{jk}$ contains a triangle-factor.
  \end{enumerate}

For the sake of brevity, let $m = |W_1| = |W_2| = |W_3|$. Without loss of generality, we may assume that $\delta \leq 1$. Let $\alpha = \delta^2/24$ and let $\beta$ be a positive constant satisfying $\beta \log(e/\beta) < \alpha\eta/30$. Moreover, let $\varepsilon = \min\{\delta/2, \eta/4, \varepsilon_{\ref{lemma_randommatching}}(\delta), \beta \cdot (\varepsilon_0)_{\ref{prop_randomgraphtypical}}(\alpha\delta/16,\delta/2), \alpha\beta\delta/16\}$ and let $\varepsilon' = 4\varepsilon/\delta$. Finally, let $C$ be sufficiently large so that $C(\log n/n)^{1/2} \geq C_{\ref{lemma_randommatching}}(\log m/m)^{1/2}$ and without loss of generality we may assume that $G(n,p)$ satisfies the assertion of Proposition~\ref{prop_smallexpansion} with $\xi = \eta\delta^2m/(2n)$ and $\xi = \eta\delta^2m/(12n)$, and Proposition~\ref{prop_randomgraphtypical} with $\varepsilon'_{\ref{prop_randomgraphtypical}}=\alpha\delta/16$ and $\delta_{\ref{prop_randomgraphtypical}} = \delta/2$.

  For all $i$ and $j$, let $q_{ij} = \eta/(d_{ij}mp)$ and select each $\varepsilon'$-good edge of $(W_i,W_j)$ independently with probability $q_{ij}$. Let $M'_{ij}$ be the set of all selected edges in $(W_i,W_j)$ and let $M_{ij} \subset M'_{ij}$ be the set of all those edges that are not incident to any other selected edge. By Proposition~\ref{prop_goodedges}, $(W_i, W_j)$ contains at most $\eta d_{ij}pm^2$ edges that are not $\varepsilon'$-good. Since each $v \in W_i$ is $\varepsilon$-good, its neighbourhood contains at most $\eta d_{12}d_{13}d_{23}p^3m^2$ edges that are not $\varepsilon'$-good. Therefore, Lemma~\ref{lemma_randommatching} applies with $E_{ij}$ being the set of non-$\varepsilon'$-good edges in $(W_i, W_j)$ and $V_i = V'_i = W_i$.

 \begin{CLAIM}
   \label{claim_largeexpansion}
    With probability $1 - o(1)$, every set $Y_i \subset W_i$ of size $\beta m$ satisfies the following. All but at most $\alpha\eta m$ edges of $M_{jk}$ belong to the neighbourhood of some vertex of $Y_i$.
  \end{CLAIM}
  \begin{proof}
    Fix a $Y_i \subset W_i$ of size $\beta m$. By Proposition \ref{prop_inheritregularity}, the triple $(Y_i, W_j, W_k)$ is $(\varepsilon/\beta, p)$-regular, and the densities of all three of its parts are at least $\delta/2$. Moreover, since we assumed that $G(n,p)$ satisfies the assertion of Proposition~\ref{prop_randomgraphtypical}, $(Y_i, W_j, W_k)$ is $\alpha\delta/16$-typical and by our assumption on $\varepsilon$, it is $(\alpha\delta/16,p)$-regular. By Proposition~\ref{prop_goodedges}, all but at most $(\alpha/2)d_{23}pm^2$ edges between $W_j$ and $W_k$ are $\alpha/2$-good, so in particular all but at most $(\alpha/2)d_{23}pm^2$ edges in $(W_j, W_k)$ belong to the neighbourhood of some vertex in $Y_i$. Hence the expected number of edges chosen among those ``bad'' edges is at most $(\alpha/2)d_{23}pm^2 q_{23} = (\alpha \eta /2) m$. Chernoff's inequality implies that the probability that more than $\alpha\eta m$ of those edges are chosen to $M'_{jk}$ is at most $e^{-\alpha\eta m/30}$. Since there are ${m \choose \beta m}$ $\beta m$-subsets of $W_i$,
    \[
    {m \choose \beta m} \leq \left(\frac{em}{\beta m}\right)^{\beta m} = e^{\beta\log(e/\beta)m},
    \]
    and $\alpha\eta/30 > \beta\log(e/\beta)$, the probability that all sets $Y_i$ have the claimed property is $1 - o(1)$.
  \end{proof}

  Lemma~\ref{lemma_randommatching} and Claim~\ref{claim_largeexpansion} imply that there exist $M_{12}$, $M_{13}$, and $M_{23}$ such that $M_{12} \cup M_{13} \cup M_{23}$ is a matching and for all $i$, $j$, and $k$ (properties 1, 2, and 3 follow from (M1), (M3), and (M4) of Lemma \ref{lemma_randommatching}, respectively, whereas property 4 follows from Claim \ref{claim_largeexpansion}):
 \begin{enumerate}
  \item
    $(\eta/2)m \leq |M_{jk}| \le 2\eta m$,
  \item \label{item_degreeWiMjk}
    the neighbourhood of every vertex in $V_i$ contains at least $(\eta/2)\delta^2p^2m$ edges of $M_{jk}$,
  \item
    the endpoints of each edge of $M_{jk}$ have at least $(1/2)\delta^2p^2m$ common neighbours in $W_i \setminus Q_i$,
  \item \label{item_expandYi}
    for every set $Y_i \subset W_i$ of size $\beta m$, all but at most $\alpha\eta m$ edges of $M_{jk}$ belong to the neighbourhood of some vertex of $Y_i$.
  \end{enumerate}

  Fix any such $M_{12}$, $M_{13}$, and $M_{23}$. Next, for each $i$, let $X_i$ be a random binomial subset of $W_i \setminus Q_i$, where each element is included with probability $\eta/5$. A simple application of Chernoff's inequality combined with Property 3 above shows that if $C$ is sufficiently large, then with probability $1 - o(1)$, for all $i$, $j$, and $k$:
  \begin{enumerate}
    \setcounter{enumi}{4}
  \item \label{item_sizeXi}
    $|X_i| \leq (\eta/4)m$,
  \item \label{item_degreeMjkXi}
    the endpoints of each edge of $M_{jk}$ have at least $(\eta/12)\delta^2p^2m$ common neighbours in $X_i$.
  \end{enumerate}
  Let $X_1$, $X_2$, and $X_3$ be arbitrary sets satisfying \ref{item_sizeXi} and \ref{item_degreeMjkXi} and note that properties (P1)--(P3) are satisfied. It remains to show that (P4) is also satisfied.

  Fix a $Z_i \subset W_i$ of size $|M_{jk}|$ such that $X_i \subset Z_i$. Let $H$ be the bipartite graph on the vertex set $Z_i \cup M_{jk}$, where a vertex $w \in Z_i$ is adjacent to an edge $\{u,v\} \in M_{jk}$ if and only if $\{u,v,w\}$ is a triangle in $(W_1,W_2,W_3)$. Clearly, it suffices to prove that $H$ contains a perfect matching. We check that $H$ satisfies the assumptions of Proposition \ref{prop_Hall} with $A = Z_i$, $B = M_{jk}$, and $L = \alpha\eta m$.

  Fix an $S \subset Z_i$. If $0 < |S| \leq (\eta/4)\delta^2m$, then $|N_H(S)| > |S|$ or otherwise there would be an $x \in [1, (\eta/4)\delta^2m]$ such that $G(n,p)$ contains some $x$ independent edges and $x$ vertices, each of which is adjacent to both ends of at least $(\eta/2)\delta^2p^2m$ of those edges, see~\ref{item_degreeWiMjk}. This would contradict our assumption that $G(n,p)$ satisfies the assertion of Proposition~\ref{prop_smallexpansion} with $\xi = \eta\delta^2m/(2n)$. On the other hand, if $|S| \geq (\eta/4)\delta^2m \geq \beta m$, then by \ref{item_expandYi}, $|M_{jk} \setminus N_H(S)| \leq \alpha\eta m$. Hence, $|N_H(S)| \geq |S|$ as long as $|Z_i \setminus S| \geq \alpha\eta m$

  Finally, fix a $T \subset M_{jk}$ with $0 < |T| \leq \alpha\eta m = (\eta/24)\delta^2m$. If $|N_H(T)| < |T|$, then there would be an $x \in [1,(\eta/24)\delta^2m]$ such that $G(n,p)$ contains $x$ vertices and $x$ independent edges whose endpoints have at least $(\eta/12)\delta^2p^2m$ common neighbours among those $x$ vertices (recall that $X_i \subset Z_i$), see~\ref{item_degreeMjkXi}. This would contradict our assumption that $G(n,p)$ satisfies the assertion of Proposition~\ref{prop_smallexpansion} with $\xi = \eta\delta^2m/(12n)$.
